#!/usr/bin/env bash
# Shared strict cleanup authority for LOCAL-ONLY lifecycle tests.
set -euo pipefail
JC_FL_TEST_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.."&&pwd)"; . "$JC_FL_TEST_ROOT/scripts/fair-launch/local-e2e/common.sh";JC_FL_TEST_AUTHORITY_PY="$JC_FL_TEST_ROOT/scripts/tests/fair_launch_local_e2e_authority.py";JC_FL_TEST_CLEANUP_PY="$JC_FL_TEST_ROOT/scripts/tests/fair_launch_local_e2e_test_cleanup.py"
jc_fl_test_root_create(){ local domain="$1" root;root="$(mktemp -d)"||return 1;chmod 700 "$root";python3 "$JC_FL_TEST_AUTHORITY_PY" root-write "$root" "$domain"||return 1;printf '%s\n' "$root";}
jc_fl_test_phase_state(){ python3 "$JC_FL_TEST_AUTHORITY_PY" phase-verify "$1/evidence/lifecycle-phase.json" 2>/dev/null;}
jc_fl_test_wait_exit(){ local pid="$1" start="$2";for _ in $(seq 1 100);do [ "$(jc_fl_e2e_proc_start "$pid")" != "$start" ]&&return 0;sleep .05;done;return 1;}
jc_fl_test_endpoint_closed(){ local endpoint="$1" port="${1#127.0.0.1:}";[[ "$endpoint" =~ ^127\.0\.0\.1:[0-9]+$ ]]||return 1;! awk -v want="0100007F:$(printf '%04X' "$port")" 'NR>1&&toupper($2)==want&&$4=="0A"{found=1}END{exit found?0:1}' /proc/net/tcp /proc/net/tcp6;}
jc_fl_test_scope_authority(){ local scope="$1" root;if [[ "$(basename "$scope")" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$ ]];then root="$(dirname "$scope")";python3 "$JC_FL_TEST_AUTHORITY_PY" root-verify "$root">/dev/null||return 1;jc_fl_test_phase_state "$scope">/dev/null||return 1;else root="$scope";python3 "$JC_FL_TEST_AUTHORITY_PY" root-verify "$root">/dev/null||return 1;fi;[ -d "$scope/evidence" ]&&[ ! -L "$scope/evidence" ]&&[ "$(readlink -f "$scope/evidence")" = "$scope/evidence" ]&&[ "$(stat -Lc '%u:%a' "$scope/evidence")" = "$(id -u):700" ];}
jc_fl_test_process_record(){ local pid="$1" marker="$2" endpoint="$3" run_dir="$4" record="$5";jc_fl_test_scope_authority "$run_dir"||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" process-record "$pid" "$marker" "$endpoint" "$run_dir" "$record";}
jc_fl_test_process_remove(){ local record="$1" signal="${2:-TERM}" identity scope pid start endpoint;case "$signal" in TERM|KILL) ;;*)return 1;;esac;scope="$(python3 "$JC_FL_TEST_CLEANUP_PY" process-scope "$record")"||return 1;jc_fl_test_scope_authority "$scope"||return 1;identity="$(python3 "$JC_FL_TEST_CLEANUP_PY" process-verify "$record")"||return 1;IFS='|' read -r pid start endpoint<<<"$identity";python3 "$JC_FL_TEST_CLEANUP_PY" process-verify "$record">/dev/null||return 1;jc_fl_test_scope_authority "$scope"||return 1;kill -s "$signal" "$pid"||return 1;jc_fl_test_wait_exit "$pid" "$start"||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" process-absence "$record">/dev/null||return 1;rm -f "$record";}
jc_fl_test_run_authority(){ local run_dir="$1";[ -d "$run_dir" ]&&[ ! -L "$run_dir" ]||return 1;python3 "$JC_FL_TEST_AUTHORITY_PY" root-verify "$(dirname "$run_dir")">/dev/null||return 1;jc_fl_test_phase_state "$run_dir">/dev/null;}
jc_fl_test_redis_remove(){ local run_dir="$1" record="${2:-$1/redis/process.json}" phase identity pid start endpoint;jc_fl_test_run_authority "$run_dir"||return 1;RUN_DIR="$run_dir";REDIS_CONFIG="$RUN_DIR/redis/redis.conf";REDIS_FINGERPRINT="$record";phase="$(jc_fl_test_phase_state "$run_dir")"||return 1;if [ ! -f "$record" ];then printf '%s\n' "$phase"|grep -Fxq REDIS_ATTEMPTED=false||return 1;return 0;fi;printf '%s\n' "$phase"|grep -Fxq REDIS_ATTEMPTED=true||return 1;if ! identity="$(jc_fl_e2e_redis_identity "$record")";then jc_fl_e2e_redis_absent "$record"&&return 0;return 1;fi;pid="$(printf '%s\n' "$identity"|sed -n 's/^PID=//p')";start="$(printf '%s\n' "$identity"|sed -n 's/^STARTTIME=//p')";endpoint="$(printf '%s\n' "$identity"|sed -n 's/^ENDPOINT=//p')";jc_fl_test_run_authority "$run_dir"&&jc_fl_e2e_phase_requires "$run_dir" REDIS_ATTEMPTED=true&&jc_fl_e2e_redis_owned "$record"&&jc_fl_e2e_redis_owned "$record"||return 1;kill "$pid"||return 1;jc_fl_test_wait_exit "$pid" "$start"||return 1;if [ -n "${JC_FL_E2E_TEST_REDIS_AFTER_EXIT_HOOK:-}" ];then case "$JC_FL_E2E_TEST_REDIS_AFTER_EXIT_HOOK" in "$run_dir"/test-hooks/*) RUN_DIR="$run_dir" REDIS_PORT="${endpoint#127.0.0.1:}" bash "$JC_FL_E2E_TEST_REDIS_AFTER_EXIT_HOOK";;*)return 1;;esac;fi;jc_fl_e2e_redis_absent "$record";}
jc_fl_test_redis_publish_recovery_authority(){ local run_dir="$1" pid_file="$1/redis/redis.pid" config="$1/redis/redis.conf" record="$1/redis/process.json" phase pid port redis_exe;jc_fl_test_run_authority "$run_dir"||return 1;phase="$(jc_fl_test_phase_state "$run_dir")"||return 1;printf '%s\n' "$phase"|grep -Fxq REDIS_ATTEMPTED=true||return 1;[ -f "$config" ]&&[ ! -L "$config" ]&&[ "$(stat -Lc '%u:%a' "$config")" = "$(id -u):600" ]&&[ ! -e "$record" ]&&[ ! -L "$record" ]||return 1;for _ in $(seq 1 50);do [ -s "$pid_file" ]&&break;sleep .1;done;[ -f "$pid_file" ]&&[ ! -L "$pid_file" ]&&[ "$(readlink -f "$pid_file")" = "$pid_file" ]&&[ "$(stat -Lc '%u:%a' "$pid_file")" = "$(id -u):600" ]||return 1;pid="$(cat "$pid_file")";[[ "$pid" =~ ^[0-9]+$ ]]||return 1;port="$(awk '$1=="port"&&NF==2{print $2}' "$config")";[[ "$port" =~ ^[0-9]+$ ]]||return 1;redis_exe="$(readlink -f "$(command -v redis-server)")"||return 1;for _ in $(seq 1 50);do python3 "$JC_FL_TEST_ROOT/scripts/fair-launch/local-e2e/redis-process-record.py" write "$pid" "$run_dir" "$config" "127.0.0.1:$port" "$redis_exe" "$record"&&return 0;sleep .1;done;return 1;}
jc_fl_test_docker(){ timeout --foreground --kill-after=5s 20s docker -H unix:///var/run/docker.sock "$@";}
jc_fl_test_container_record(){ local id="$1" run="$2" component="$3" run_dir="$4" record="$5" inspect;inspect="${record}.inspect.new";jc_fl_test_run_authority "$run_dir"&&jc_fl_e2e_phase_requires "$run_dir" DOCKER_ATTEMPTED=true||return 1;[[ "$id" =~ ^[0-9a-f]{64}$ ]]||return 1;[ ! -e "$record" ]&&[ ! -L "$record" ]&&[ ! -e "$inspect" ]&&[ ! -L "$inspect" ]||return 1;umask 077;jc_fl_test_docker inspect "$id">"$inspect"||return 1;chmod 600 "$inspect";python3 "$JC_FL_TEST_CLEANUP_PY" container-record "$inspect" "$run" "$component" "$run_dir" "$record"||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$record">/dev/null||return 1;}
jc_fl_test_container_recover_absence(){ local record="$1" run_dir removal post raw absence id rc stage;run_dir="$(dirname "$(dirname "$record")")";removal="${record}.removal.json";post="${record}.post-rm-query";raw="${record}.post-rm-query.raw";absence="$(dirname "$record")/docker-absence.json";jc_fl_test_run_authority "$run_dir"&&jc_fl_e2e_phase_requires "$run_dir" DOCKER_ATTEMPTED=true||return 1;[ -f "$record" ]&&[ -f "$removal" ]||return 1;stage="$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$record")"||return 1;id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$record")"||return 1;umask 077;if [ -e "$post" ]||[ -L "$post" ];then python3 "$JC_FL_TEST_CLEANUP_PY" query-verify "$post" "$record">/dev/null||return 1;else jc_fl_e2e_evidence_target "$raw"||return 1;if jc_fl_test_docker inspect --format '{{.Id}}' "$id">"$raw" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "$raw";[ "$rc" -ne 0 ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" query-write "$record" "$raw" "$rc" "$post"||return 1;fi;case "$stage" in AUTHORIZED_BEFORE_RM)python3 "$JC_FL_TEST_CLEANUP_PY" absence-promote "$record" "$removal" "$post" "$absence"||return 1;;RM_SUCCEEDED_QUERY_PENDING)python3 "$JC_FL_TEST_CLEANUP_PY" absence-write "$record" "$removal" "$post" "$absence"||return 1;;*)return 1;;esac;python3 "$JC_FL_TEST_CLEANUP_PY" absence-verify "$absence">/dev/null;}
jc_fl_test_container_remove(){
 local record="$1" run_dir inspect1 inspect2 removal post raw absence id rc stage=''
 run_dir="$(dirname "$(dirname "$record")")";inspect1="${record}.inspect.1";inspect2="${record}.inspect.2";removal="${record}.removal.json";post="${record}.post-rm-query";raw="${record}.post-rm-query.raw";absence="$(dirname "$record")/docker-absence.json"
 jc_fl_test_run_authority "$run_dir"&&jc_fl_e2e_phase_requires "$run_dir" DOCKER_ATTEMPTED=true||return 1;umask 077;[ ! -e "$absence" ]||return 1
 id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$record")"||return 1
 if [ -f "$removal" ];then stage="$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$record")"||return 1;fi
 if [ "$stage" = RM_SUCCEEDED_QUERY_PENDING ];then jc_fl_test_container_recover_absence "$record";return;fi
 if [ "$stage" = AUTHORIZED_BEFORE_RM ];then jc_fl_test_container_recover_absence "$record"&&return 0;fi
 jc_fl_e2e_evidence_target "$inspect1"||return 1;if jc_fl_test_docker inspect "$id">"$inspect1" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "$inspect1"
 if [ "$rc" -ne 0 ];then [ "$stage" = AUTHORIZED_BEFORE_RM ]||return 1;jc_fl_test_container_recover_absence "$record";return;fi
 python3 "$JC_FL_TEST_CLEANUP_PY" container-verify "$record" "$inspect1">/dev/null||return 1
 jc_fl_e2e_evidence_target "$inspect2"||return 1;jc_fl_test_docker inspect "$id">"$inspect2" 2>&1||return 1;chmod 600 "$inspect2";python3 "$JC_FL_TEST_CLEANUP_PY" container-verify "$record" "$inspect2">/dev/null||return 1
 if [ -n "$stage" ];then [ "$stage" = AUTHORIZED_BEFORE_RM ]||return 1;else python3 "$JC_FL_TEST_CLEANUP_PY" removal-write "$record" "$removal">/dev/null||return 1;fi
 jc_fl_e2e_evidence_target "${record}.rm-output"||return 1;if [ "${JC_FL_E2E_TEST_CONTAINER_RM_FAIL:-}" = 1 ];then jc_fl_e2e_evidence_target "${record}.rm-failure"||return 1;printf '%s\n' injected-rm-failure >"${record}.rm-failure";chmod 600 "${record}.rm-failure";return 1;fi
 jc_fl_test_run_authority "$run_dir"||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" removal-verify "$removal" "$record" AUTHORIZED_BEFORE_RM>/dev/null||return 1;if jc_fl_test_docker rm -f "$id">"${record}.rm-output" 2>&1;then rc=0;else rc=$?;fi;chmod 600 "${record}.rm-output";[ "$rc" -eq 0 ]||return 1
 python3 "$JC_FL_TEST_CLEANUP_PY" removal-update "$removal" "$record" AUTHORIZED_BEFORE_RM RM_SUCCEEDED_QUERY_PENDING>/dev/null||return 1
 jc_fl_e2e_evidence_target "$raw"||return 1;if [ "${JC_FL_E2E_TEST_CONTAINER_POST_RM_QUERY_FAIL:-}" = 1 ];then printf '%s\n' injected-post-rm-query-failure >"$raw";chmod 600 "$raw";return 1;fi
 jc_fl_test_container_recover_absence "$record"
}
jc_fl_test_container_finalize_absent(){ jc_fl_test_container_recover_absence "$1";}
jc_fl_test_lifecycle_container_cleanup(){ local run_dir="$1" source removal evidence absence candidate id covered;local -a sources=() absences=();mapfile -d '' -t sources < <(find "$run_dir/evidence" -mindepth 1 -maxdepth 1 -name '*.source.json' -print0);for source in "${sources[@]}";do evidence="${source%.source.json}";removal="${source}.removal.json";absence="${evidence}.absence.json";id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$source")"||return 1;if [ -e "$absence" ]||[ -L "$absence" ];then [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$absence" "$source")" = "$id" ]||return 1;elif [ -e "$removal" ]||[ -L "$removal" ];then RUN_DIR="$run_dir" RUN_ID="$(basename "$run_dir")" jc_fl_e2e_docker_remove_exact "$id" "$evidence"||return 1;fi;done;for source in "${sources[@]}";do evidence="${source%.source.json}";removal="${source}.removal.json";absence="${evidence}.absence.json";id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$source")"||return 1;if [ -e "$absence" ]||[ -L "$absence" ];then [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$absence" "$source")" = "$id" ]||return 1;continue;fi;[ ! -e "$removal" ]&&[ ! -L "$removal" ]||return 1;covered=0;mapfile -d '' -t absences < <(find "$run_dir/evidence" -mindepth 1 -maxdepth 1 \( -name 'docker-absence.json' -o -name '*.absence.json' \) -print0);for candidate in "${absences[@]}";do if [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$candidate" "$source" 2>/dev/null || true)" = "$id" ];then covered=1;break;fi;done;[ "$covered" = 1 ]&&continue;RUN_DIR="$run_dir" RUN_ID="$(basename "$run_dir")" jc_fl_e2e_docker_remove_exact "$id" "$evidence"||return 1;done;}
jc_fl_test_chain_artifacts(){ local run_dir="$1" evidence="$1/evidence" file source query removal;local -a files=();mapfile -d '' -t files < <(find "$evidence" -mindepth 1 -maxdepth 1 -name '*.rm-failure' -print0);[ "${#files[@]}" -eq 0 ]||return 1;mapfile -d '' -t files < <(find "$evidence" -mindepth 1 -maxdepth 1 -name '*.post-rm-query.raw' -print0);for file in "${files[@]}";do [ -f "$file" ]&&[ ! -L "$file" ]&&[ "$(readlink -f "$file")" = "$file" ]&&[ "$(stat -Lc '%u:%a' "$file")" = "$(id -u):600" ]||return 1;query="${file%.raw}";source="${query%.post-rm-query}";[ -e "$source" ]&&[ -e "$query" ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" query-verify "$query" "$source">/dev/null||return 1;done;mapfile -d '' -t files < <(find "$evidence" -mindepth 1 -maxdepth 1 -name '*.rm-output' -print0);for file in "${files[@]}";do [ -f "$file" ]&&[ ! -L "$file" ]&&[ "$(readlink -f "$file")" = "$file" ]&&[ "$(stat -Lc '%u:%a' "$file")" = "$(id -u):600" ]||return 1;source="${file%.rm-output}";[ "$source" = "$evidence/test-container-cleanup.json" ]||source="${source}.source.json";removal="${source}.removal.json";[ -e "$source" ]&&[ -e "$removal" ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$source">/dev/null||return 1;done;mapfile -d '' -t files < <(find "$evidence" -mindepth 1 -maxdepth 1 \( -name '*.inspect.new' -o -name '*.inspect.1' -o -name '*.inspect.2' \) -print0);for file in "${files[@]}";do [ -f "$file" ]&&[ ! -L "$file" ]&&[ "$(readlink -f "$file")" = "$file" ]&&[ "$(stat -Lc '%u:%a' "$file")" = "$(id -u):600" ]||return 1;case "$file" in *.inspect.new)source="${file%.inspect.new}";[ -e "$source" ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" container-evidence-verify "$source" "$file">/dev/null||return 1;;*.inspect.1|*.inspect.2)source="${file%.inspect.1}";source="${source%.inspect.2}";[ -e "$source" ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" container-verify "$source" "$file">/dev/null||return 1;;*)return 1;;esac;done;}
jc_fl_test_run_absent(){ local run_dir="$1" record="$1/evidence/test-container-cleanup.json" absence_record="$1/evidence/docker-absence.json" phase source removal query expected evidence absence id covered proof_count=0;local -a sources=() removals=() queries=() all_absences=();jc_fl_test_run_authority "$run_dir"||return 1;phase="$(jc_fl_test_phase_state "$run_dir")"||return 1;if [ -e "$run_dir/redis/process.json" ]||[ -L "$run_dir/redis/process.json" ];then printf '%s\n' "$phase"|grep -Fxq REDIS_ATTEMPTED=true||return 1;jc_fl_e2e_redis_absent "$run_dir/redis/process.json"||return 1;else printf '%s\n' "$phase"|grep -Fxq REDIS_ATTEMPTED=false||return 1;fi;if [ -e "$absence_record" ]||[ -L "$absence_record" ];then [ -e "$record" ]||[ -L "$record" ]||return 1;[ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$absence_record" "$record")" = "$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$record")" ]||return 1;proof_count=$((proof_count+1));elif [ -e "$record" ]||[ -L "$record" ];then return 1;fi;mapfile -d '' -t sources < <(find "$run_dir/evidence" -mindepth 1 -maxdepth 1 -name '*.source.json' -print0);mapfile -d '' -t removals < <(find "$run_dir/evidence" -mindepth 1 -maxdepth 1 -name '*.removal.json' -print0);mapfile -d '' -t queries < <(find "$run_dir/evidence" -mindepth 1 -maxdepth 1 -name '*.post-rm-query' -print0);mapfile -d '' -t all_absences < <(find "$run_dir/evidence" -mindepth 1 -maxdepth 1 -name '*.absence.json' -print0);if [ -e "$record" ]||[ -L "$record" ]||[ -e "$absence_record" ]||[ -L "$absence_record" ]||[ "${#sources[@]}" -gt 0 ]||[ "${#removals[@]}" -gt 0 ]||[ "${#queries[@]}" -gt 0 ]||[ "${#all_absences[@]}" -gt 0 ];then printf '%s\n' "$phase"|grep -Fxq DOCKER_ATTEMPTED=true||return 1;fi;for removal in "${removals[@]}";do source="${removal%.removal.json}";[ -e "$source" ]||[ -L "$source" ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "$removal" "$source">/dev/null||return 1;if [ "$source" = "$record" ];then expected="$absence_record";elif [[ "$source" = *.source.json ]];then expected="${source%.source.json}.absence.json";else return 1;fi;[ -e "$expected" ]||[ -L "$expected" ]||return 1;[ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$expected" "$source")" = "$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$source")" ]||return 1;done;for query in "${queries[@]}";do source="${query%.post-rm-query}";[ -e "$source" ]||[ -L "$source" ]||return 1;python3 "$JC_FL_TEST_CLEANUP_PY" query-verify "$query" "$source">/dev/null||return 1;if [ "$source" = "$record" ];then expected="$absence_record";elif [[ "$source" = *.source.json ]];then expected="${source%.source.json}.absence.json";else return 1;fi;[ -e "$expected" ]||[ -L "$expected" ]||return 1;done;for absence in "${all_absences[@]}";do python3 "$JC_FL_TEST_CLEANUP_PY" absence-verify "$absence">/dev/null||return 1;done;for source in "${sources[@]}";do evidence="${source%.source.json}";absence="${evidence}.absence.json";id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$source")"||return 1;if [ -e "$absence" ]||[ -L "$absence" ];then [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$absence" "$source")" = "$id" ]||return 1;else covered=0;for absence in "$absence_record" "${all_absences[@]}";do [ -e "$absence" ]||[ -L "$absence" ]||continue;if [ "$(python3 "$JC_FL_TEST_CLEANUP_PY" absence-covers "$absence" "$source" 2>/dev/null || true)" = "$id" ];then covered=1;break;fi;done;[ "$covered" = 1 ]||return 1;fi;proof_count=$((proof_count+1));done;if [ "$proof_count" -eq 0 ];then printf '%s\n' "$phase"|grep -Fxq DOCKER_ATTEMPTED=false||return 1;fi;}
jc_fl_test_run_delete(){ local run_dir="$1" before after;jc_fl_test_run_authority "$run_dir"||return 1;before="$(stat -Lc '%d:%i:%u:%a' "$run_dir")"||return 1;jc_fl_test_run_absent "$run_dir"||return 1;jc_fl_test_chain_artifacts "$run_dir"||return 1;jc_fl_test_run_authority "$run_dir"||return 1;after="$(stat -Lc '%d:%i:%u:%a' "$run_dir")"||return 1;[ "$after" = "$before" ]||return 1;rm -rf "$run_dir";}
jc_fl_test_run_cleanup(){
 local run_dir="$1" record="$1/evidence/test-container-cleanup.json" absence="$1/evidence/docker-absence.json" stage
 [ -d "$run_dir" ]||return 0;jc_fl_test_run_authority "$run_dir"||return 1
 if [ -f "$absence" ];then
  python3 "$JC_FL_TEST_CLEANUP_PY" absence-verify "$absence">/dev/null||return 1
 elif [ -f "$record" ];then
  if [ -f "${record}.removal.json" ];then
   stage="$(python3 "$JC_FL_TEST_CLEANUP_PY" removal-stage "${record}.removal.json" "$record")"||return 1
   case "$stage" in AUTHORIZED_BEFORE_RM)jc_fl_test_container_remove "$record"||return 1;;RM_SUCCEEDED_QUERY_PENDING)jc_fl_test_container_recover_absence "$record"||return 1;;*)return 1;;esac
  else
   jc_fl_test_container_remove "$record"||return 1
  fi
 fi
 jc_fl_test_lifecycle_container_cleanup "$run_dir"||return 1
 jc_fl_test_redis_remove "$run_dir"||return 1
 jc_fl_test_run_delete "$run_dir"
}
jc_fl_test_root_finalize(){ local supplied="$1" root child name ok=1 before after marker;[ -n "$supplied" ]&&[ -e "$supplied" ]&&[ -d "$supplied" ]&&[ ! -L "$supplied" ]||return 1;before="$(stat -Lc '%d:%i:%u:%a' "$supplied")"||return 1;[ "${before##*:}" = 700 ]||return 1;root_info="$(python3 "$JC_FL_TEST_AUTHORITY_PY" root-verify "$supplied")"||return 1;IFS='|' read -r root _ _ marker<<<"$root_info";[ "$root" != / ]||return 1;while IFS= read -r -d '' child;do if [ -d "$child" ]&&[ ! -L "$child" ];then name="$(basename "$child")";[[ "$name" =~ ^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$ ]]||{ ok=0;continue;};jc_fl_test_run_cleanup "$child"||ok=0;elif [ -L "$child" ];then ok=0;fi;done < <(find "$root" -mindepth 1 -maxdepth 1 -print0);[ "$ok" = 1 ]||return 1;[ "${JC_FL_E2E_TEST_ROOT_FINALIZE_FAIL:-0}" != 1 ]||{ printf '%s\n' injected-root-finalization-failure >"$root/root-finalization-failure";chmod 600 "$root/root-finalization-failure";return 1;};after="$(stat -Lc '%d:%i:%u:%a' "$supplied")"||return 1;[ "$after" = "$before" ]||return 1;python3 "$JC_FL_TEST_AUTHORITY_PY" root-verify "$supplied">/dev/null||return 1;find "$root" -mindepth 1 -maxdepth 1 -type f ! -path "$marker" -delete;rm -f "$marker";[ -z "$(find "$root" -mindepth 1 -maxdepth 1 -print -quit)" ]||return 1;rmdir "$root";}
jc_fl_test_bounded_teardown(){ local root="$1" run="$2" rc;set +e;JC_FL_E2E_STATE_ROOT="$root" timeout --foreground --kill-after=5s 120s bash "$JC_FL_TEST_ROOT/scripts/fair-launch/local-e2e/teardown.sh" "$run">/dev/null 2>&1;rc=$?;set -e;[ "$rc" = 0 ]&&[ ! -d "$root/$run" ];}
jc_fl_test_canonical_container_record(){ local run_dir="$1" record="$2";JC_FL_E2E_STATE_ROOT="$(dirname "$run_dir")";jc_fl_e2e_load_state "$(basename "$run_dir")";jc_fl_e2e_mysql_container_static_owned "$MYSQL_CONTAINER_ID" "$MYSQL_IMAGE_REF" "$MYSQL_IMAGE_ID" "$MYSQL_PORT" "$RUN_ID" "$MYSQL_NAME" "$RUN_DIR"||return 1;jc_fl_test_container_record "$MYSQL_CONTAINER_ID" "$RUN_ID" mysql "$run_dir" "$record";}
